private void permuteUtils(int[] nums, int start, List<List<Integer>> result) {
        if (start == nums.length) {
            result.add(new ArrayList<>(Arrays.stream(nums).boxed().collect(Collectors.toList())));
            return;
        }

        for (int i = start; i < nums.length; i++) {
            swap(nums, start, i);
            permuteUtils(nums, start + 1, result);
            swap(nums, start, i);
        }
    }

