public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Determine the size of the n-teresting space
    int spaceSize = n;

    // Check if the starting and ending n-tersections are within the space
    if (start[0] >= spaceSize || start[1] >= spaceSize || end[0] >= spaceSize || end[1] >= spaceSize) {
        return "cannot be travelled";
    }

    // Use BFS to find if there is a path from start to end
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    Set<int[]> visited = new HashSet<>();
    visited.add(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];

        // Check if the current position is the ending n-tersection
        if (x == end[0] && y == end[1]) {
            return "can be travelled";
        }

        // Try moving in all four directions
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        for (int[] direction : directions) {
            int newX = x + direction[0];
            int newY = y + direction[1];

            // Check if the new position is within the space and is unvisited
            if (newX >= 0 && newX < spaceSize && newY >= 0 && newY < spaceSize && !visited.contains(new int[]{newX, newY})) {
                queue.add(new int[]{newX, newY});
                visited.add(new int[]{newX, newY});
            }
        }
    }

    // If no path is found from start to end
    return "cannot be travelled";
}

