private int dfs(ArrayList<Integer>[] adj, int node, boolean[] hasApple, boolean[] visited) {
        int totalTime = 0;
        for (int neighbor : adj[node]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                totalTime += dfs(adj, neighbor, hasApple, visited);
            }
        }

        if (node == 0 || hasApple[node]) {
            totalTime += 2; // 1 sec to collect and return
        }

        return totalTime;
    }

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (!s.isEmpty()) {
        // Step 1: Find the smallest character not already in the result
        char smallest = 'z' + 1;
        for (char ch : s.toCharArray()) {
            if (ch < smallest && Character.isLetter(ch)) {
                smallest = ch;
            }
        }
        // Step 2: Remove all occurrences of the smallest character
        s = s.replace(smallest, '\0');
        result.append(smallest);
        // Step 3: Find the largest character not already in the result
        char largest = 'a' - 1;
        for (char ch : s.toCharArray()) {
            if (ch > largest && Character.isLetter(ch)) {
                largest = ch;
            }
        }
        // Step 4: Remove all occurrences of the largest character
        s = s.replace(largest, '\0');
        result.append(largest);
    }
    return result.toString();
}

