private static int countPermutationsWithMemo(int[] A, int[] memo, int index) {
    if (index < 0) {
        return 1;
    }

    if (memo[index] != -1) {
        return memo[index];
    }

    int count = 0;

    // Iterate through all possible first elements for the current subarray
    for (int i = 0; i < A.length; i++) {
        if (Math.pow(A[index], 2) + Math.pow(A[i], 2) == Math.pow(A[index] + A[i], 2)) {
            int[] newArray = Arrays.copyOfRange(A, 0, index);
            newArray[index] = A[i];
            count += countPermutationsWithMemo(newArray, memo, index - 1);
        }
    }

    memo[index] = count;
    return count;
}

public static int largestRectangleArea(int[] heights) {
    int ans = 0;
    Stack<Integer> stack = new Stack<>();
    for(int i = 0; i < heights.length ; i++){
        while(!stack.isEmpty() && heights[i] <= heights[stack.peek()]){
            int h = heights[stack.pop()];
            int width = stack.isEmpty()?i:i-stack.peek()-1;
            ans = Math.max(ans,h*width);
        }
        stack.push(i);
    }
    while(!stack.isEmpty()){
        int h = heights[stack.pop()];
        int width = stack.isEmpty()?heights.length:i-stack.peek()-1;
        ans = Math.max(ans,h*width);
    }
    return ans;
}

