public static boolean isBoomerang(int[][] points) {
    int crosses_x = 0;
    int crosses_y = 0;
    int count = points.length;
    for (int i = 0; i < count; i++) {
        int next_x = (i+1) % count;
        int x1 = points[i][0];
        int y1 = points[i][1];
        int x2 = points[next_x][0];
        int y2 = points[next_x][1];
        if (x1 * (y2 - y1) - y1 * (x2 - x1) == 0) {
            crosses_y++;
        }
        if (y1 * (x2 - x1) - x1 * (y2 - y1) == 0) {
            crosses_x++;
        }
    }
    if (crosses_x == 0 || crosses_y == 0 || crosses_x == 2 || crosses_y == 2) {
        return true;
    }
    return false;
}

