public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        List<Integer> tmp = new ArrayList<>();
        tmp.add(1);

        while (tmp.size() < n) {
            for (int i = 0; i < tmp.size(); i++) {
                int num = tmp.get(i);
                tmp.add(num * 10);
                if (num != n) {
                    tmp.add(num * 10 + 1);
                }
            }
        }

        for (int i = 0; i < tmp.size(); i++) {
            if (tmp.get(i) > n) {
                break;
            }
            result.add(tmp.get(i));
        }

        return result;
    }

public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    Map<Integer, Integer> numCount = new HashMap<>();
    for (int num : nums) {
        numCount.put(num, numCount.getOrDefault(num, 0) + 1);
    }
    for (int num : numCount.keySet()) {
        if (numCount.get(num) == 1) {
            sum += num;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            min = Math.min(min, 1 + dp[i - j * j]);
        }
        dp[i] = min;
    }

    return dp[n];
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder sb = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        for (int i = 0; i < word.length(); i++) {
            reversedWord.append(word.charAt(word.length() - i - 1));
        }
        sb.append(reversedWord.toString()).append(" ");
    }

    return sb.toString().trim();
}
